// PWA icons, cut once from assets/icon-master-1024.png via sips and embedded
// as base64 -- no runtime image processing, no committed generated PNGs.
// Plain-value constants only, no handlers -- same entry-module-export
// constraint as lib.js (see lib.js header): workerd requires every
// top-level named export of the *entry* module to be a function/class, so
// plain-value constants live here instead. Nothing here is ever
// interpolated into a client-side script (unlike lib.js's rendering
// helpers), so the esbuild __name-wrap toString trap does not apply.
export const ICON_180_B64 = '';
export const ICON_192_B64 = '';
export const ICON_512_B64 = '';
export const FAVICON_32_B64 = ''; // 32x32 PNG, resized offline from ICON_180_B64 via ImageMagick — see docs/ARCHITECTURE.md
